"""Export the actual rendered REDPAD project to a read-only isolated review dashboard.
The original Streamlit UI reads these same source artifacts and isolated SQLite records.
"""
import json,shutil,sys,hashlib
from pathlib import Path
P=Path(__file__).parent;ROOT=P.parents[1]/'redpad_media'/'drama'/'ghor117_ep01'
def main(dest):
 dest=Path(dest);dest.mkdir(parents=True,exist_ok=True)
 plan=json.loads((P/'plan.json').read_text());qa=json.loads((ROOT/'qa_report.json').read_text())
 if not qa.get('passed'):raise ValueError('No passing final QA')
 for name in ['Ghor_117_EP01_Animated_Drama.mp4','subtitles.bn.srt','qa_report.json']:
  shutil.copyfile(ROOT/name,dest/name)
 for name in ['plan.json','production_bible.md','screenplay.md','season_outline.md']:
  shutil.copyfile(P/name,dest/name)
 shutil.copytree(ROOT/'references',dest/'references',dirs_exist_ok=True)
 for name in ['review_record.json','youtube_publication.json']:
  if (ROOT/name).exists():shutil.copyfile(ROOT/name,dest/name)
 data=dict(plan=plan,qa=qa,source_branch='feature/video-music-editing-studio',review=json.loads((ROOT/'review_record.json').read_text()) if (ROOT/'review_record.json').exists() else {},youtube=json.loads((ROOT/'youtube_publication.json').read_text()) if (ROOT/'youtube_publication.json').exists() else dict(status='not_uploaded'))
 (dest/'project.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 (dest/'index.html').write_text(HTML)
 print('Exported actual project',qa['sha256'])
